    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Repeat each panel's pattern into the adjacent panel by reflection;
    # preserve the colored lattice separators.
    vc=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1 and grid[0][c]!=0]
    hr=[r for r in range(h) if len(set(grid[r]))==1 and grid[r][0]!=0]
    xs=[-1]+vc+[w]; ys=[-1]+hr+[h]
    px=[(a+1,b) for a,b in zip(xs,xs[1:])]
    py=[(a+1,b) for a,b in zip(ys,ys[1:])]
    for y0,y1 in py:
        for (x0,x1),(u0,u1) in zip(px,px[1:]):
            for y in range(y0,y1):
                for k in range(min(x1-x0,u1-u0)):
                    val=grid[y][x0+k]
                    if val and grid[y][u0+k]==0:
                        g[y][u0+k]=val
    for (y0,y1),(z0,z1) in zip(py,py[1:]):
        for x0,x1 in px:
            for k in range(min(y1-y0,z1-z0)):
                for x in range(x0,x1):
                    val=grid[y0+k][x]
                    if val and grid[z0+k][x]==0:
                        g[z0+k][x]=val
    return g
