    panels=[(a+1,b) for a,b in zip(xs,xs[1:])]
    bands=[(a+1,b) for a,b in zip(ys,ys[1:])]
    # Each panel motif propagates downward to its corresponding panel in the next band.
    for (y0,y1),(z0,z1) in zip(bands,bands[1:]):
        nh=min(y1-y0,z1-z0)
        for x0,x1 in panels:
            nw=x1-x0
            for dy in range(nh):
                for dx in range(nw):
                    val=grid[y0+dy][x0+dx]
                    if val and grid[z0+dy][x0+dx]==0:
                        g[z0+dy][x0+dx]=val
    return g
